'use strict';
window.RepoAccount=(()=>{
let user=null,enabled=false,analyticsEnabled=false,launchAnalyticsEnabled=false,googleEnabled=false,ready=false,liked=new Set(),likedRepos=new Map(),forks=new Map(),forkSync={},forkError=null,syncing=false,refreshEpoch=0,legal={active:false,required:false},pending=new Set(),guest=new Set(),queue=[],sending=false,timer,initial=true;
try{guest=new Set(JSON.parse(localStorage.getItem('reposhelf.likes.guest.v1')||'[]').filter(x=>typeof x==='string'))}catch{}
const notify=()=>window.dispatchEvent(new Event('reposhelf-account'));
function statusMessage(status){return status===429?'Too many requests. Please wait a moment and try again.':status>=500?'RepoShelf is having trouble right now. Please try again in a moment.':'This action could not be completed.'}
function friendlyError(e){if(e?.name==='AbortError')return e;const error=new Error(e?.name==='TimeoutError'?'The request took too long. Please try again.':navigator.onLine===false?'You appear to be offline. Check your connection and try again.':'Could not reach RepoShelf. Check your connection and try again.');error.code='network';return error}
async function request(path,options={}){let response;try{response=await fetch(path,{credentials:'same-origin',headers:{'Content-Type':'application/json'},...options,signal:options.signal||AbortSignal.timeout(30000)})}catch(e){throw friendlyError(e)}const data=await response.json().catch(()=>null);if(!response.ok||!data){const error=new Error(data?.error?.message||statusMessage(response.status));error.status=response.status;error.code=data?.error?.code;throw error}return data}
async function loadForks(){const identity=user?.id;if(!identity){forks=new Map();forkSync={};return}const saved=new Map();let cursor,state;do{const data=await request('/api/forks'+(cursor?'?cursor='+encodeURIComponent(cursor):''));for(const row of data.items)saved.set(row.id,row);cursor=data.nextCursor;state=data.sync}while(cursor);if(user?.id!==identity)return;forks=saved;forkSync=state||{};forkError=null;notify()}
async function syncForks(){if(legal.required){location.href='/legal.html';return}if(!user)throw Error('Sign in with GitHub to verify your public forks.');if(syncing)return;syncing=true;forkError=null;notify();const identity=user.id;try{const priorForks=new Set(forks.keys());const result=await request('/api/forks',{method:'POST',body:'{}'});if(user?.id===identity){await loadForks();for(const [id,row] of forks)if(!priorForks.has(id)&&row.available!==false)track('verified_fork',id)}return result}catch(e){if(user?.id===identity)forkError=e.message;throw e}finally{syncing=false;notify()}}
async function refresh(){const epoch=++refreshEpoch;try{const data=await request('/api/auth');if(epoch!==refreshEpoch)return;legal=data.legal||{active:false,required:false};enabled=data.enabled;analyticsEnabled=data.analyticsEnabled;launchAnalyticsEnabled=data.launchAnalyticsEnabled===true;googleEnabled=data.googleEnabled===true;if(user?.id!==data.user?.id){liked=new Set();likedRepos=new Map();forks=new Map();forkSync={};forkError=null}user=data.user;if(user){const identity=user.id,ids=new Set(),details=new Map();let cursor;do{const page=await request('/api/collection'+(cursor?'?cursor='+encodeURIComponent(cursor):''));page.items.forEach(x=>{ids.add(x.id);if(x.repo)details.set(x.id,x.repo)});cursor=page.nextCursor}while(cursor);if(epoch!==refreshEpoch||user?.id!==identity)return;liked=ids;likedRepos=details;try{await loadForks()}catch(e){forkError=e.message}}else{liked=new Set();likedRepos=new Map();forks=new Map();forkSync={}}}catch(e){if(initial){user=null;liked=new Set();likedRepos=new Map();forks=new Map()}else throw e}finally{initial=false;ready=true;notify()}if(analyticsEnabled&&!pageTracked)pageTracked=track('page_view')===true;if(user?.githubConnected){try{const pendingSignIn=JSON.parse(sessionStorage.getItem('reposhelf.analytics.signin')||'null');if(pendingSignIn){if(user.admin||Date.now()-pendingSignIn.at>=86400000||track('sign_in_complete',pendingSignIn.project,pendingSignIn.shelf))sessionStorage.removeItem('reposhelf.analytics.signin')}}catch{}}void flush();if(user?.githubConnected&&!forkError&&Date.now()-Date.parse(forkSync.lastAttemptAt||'1970-01-01')>21600000)void syncForks().catch(()=>{})}
let pageTracked=false;
async function toggle(id,repo){if(legal.required){location.href='/legal.html';return}if(!user)throw Error('Sign in to like projects.');if(pending.has(id))return;id=[...liked].find(saved=>saved.toLowerCase()===id.toLowerCase())||id;const identity=user.id,was=liked.has(id);pending.add(id);was?liked.delete(id):liked.add(id);notify();try{const result=await request('/api/collection',{method:was?'DELETE':'PUT',body:JSON.stringify({id,repo:repo?{name:repo.name,description:repo.description,category:repo.category,language:repo.language,demo:repo.demo}:undefined})});if(user?.id===identity){if(!was){track('like',result.id);if(result.id!==id){liked.delete(id);liked.add(result.id)}if(repo)likedRepos.set(result.id,{full:result.id,name:repo.name,description:repo.description,category:repo.category,language:repo.language,demo:repo.demo,color:'#25392f',ink:'#d1e5c5'})}else likedRepos.delete(id)}}catch(e){if(user?.id===identity){was?liked.add(id):liked.delete(id)}throw e}finally{pending.delete(id);notify()}}
async function importGuest(){if(!user)throw Error('Sign in first.');const identity=user.id;for(const id of guest)if(!liked.has(id)){await request('/api/collection',{method:'PUT',body:JSON.stringify({id})});if(user?.id!==identity)throw Error('Your account changed. Sign in again before importing.');liked.add(id)}guest.clear();try{localStorage.removeItem('reposhelf.likes.guest.v1')}catch{}notify()}
async function signout(){await request('/api/auth?action=signout',{method:'POST',body:'{}'});refreshEpoch++;projectShelves.clear();user=null;liked=new Set();likedRepos=new Map();forks=new Map();forkSync={};forkError=null;notify()}
function visitorSession(){let visitor,session;try{visitor=localStorage.getItem('reposhelf.analytics.visitor');if(!visitor){visitor=crypto.randomUUID();localStorage.setItem('reposhelf.analytics.visitor',visitor)}let saved=JSON.parse(sessionStorage.getItem('reposhelf.analytics.session')||'null');if(!saved||Date.now()-saved.last>1800000)saved={id:crypto.randomUUID()};saved.last=Date.now();sessionStorage.setItem('reposhelf.analytics.session',JSON.stringify(saved));session=saved.id}catch{visitor=fallbackVisitor;session=fallbackSession}return {visitor,session}}
const fallbackVisitor=crypto.randomUUID(),fallbackSession=crypto.randomUUID();
const projectShelves=new Map();function track(kind,project,shelf,query){if(['like','verified_fork','sign_in_start','sign_in_complete'].includes(kind)&&!launchAnalyticsEnabled)return false;let consent=false;try{consent=localStorage.getItem('reposhelf.analytics.consent.v2')==='yes'}catch{}if(!consent||legal.required||ready&&!analyticsEnabled||user?.admin||location.pathname==='/admin.html'||navigator.globalPrivacyControl||navigator.doNotTrack==='1')return false;if(project&&shelf)projectShelves.set(project,shelf);if(projectShelves.size>100)projectShelves.delete(projectShelves.keys().next().value);const origin=shelf||projectShelves.get(project);queue.push({id:crypto.randomUUID(),kind,...kind==='search'&&typeof query==='string'?{query:query.slice(0,80)}:{},...project?{project}:{},...origin?{shelf:origin}:{}});if(queue.length>200)queue.splice(0,queue.length-200);clearTimeout(timer);timer=setTimeout(flush,500);return true}
async function flush(){let consent=false;try{consent=localStorage.getItem('reposhelf.analytics.consent.v2')==='yes'}catch{}if(!ready)return;if(!consent||!analyticsEnabled||legal.required||user?.admin||location.pathname==='/admin.html'||navigator.globalPrivacyControl||navigator.doNotTrack==='1'){queue=[];clearTimeout(timer);return}if(sending||!queue.length)return;sending=true;const batch=queue.slice(0,10);try{const response=await fetch('/api/analytics',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({...visitorSession(),consent:true,consentVersion:2,events:batch}),keepalive:true,signal:AbortSignal.timeout(10000)});if(response.ok||response.status<500&&![408,429].includes(response.status)){const ids=new Set(batch.map(e=>e.id));queue=queue.filter(e=>!ids.has(e.id))}}catch{}finally{sending=false;if(queue.length)timer=setTimeout(flush,5000)}}
function privacyChanged(){try{if(localStorage.getItem('reposhelf.analytics.consent.v2')!=='yes'){sessionStorage.removeItem('reposhelf.analytics.signin');projectShelves.clear()}}catch{}if(!pageTracked)pageTracked=track('page_view')===true;void flush()}window.addEventListener('storage',e=>{if(e.key==='reposhelf.analytics.consent.v2')privacyChanged()});window.addEventListener('reposhelf-privacy',privacyChanged);
document.addEventListener('click',e=>{const link=e.target.closest?.('a[href]');if(!link||!link.getAttribute('href')?.startsWith('/api/auth?action=start'))return;if(track('sign_in_start')){try{sessionStorage.setItem('reposhelf.analytics.signin',JSON.stringify({at:Date.now()}))}catch{}}});
window.addEventListener('pagehide',()=>void flush());
document.addEventListener('visibilitychange',()=>{if(document.hidden)void flush()});
refresh().then(()=>{if(legal.required&&location.pathname!=='/legal.html'&&location.pathname!=='/terms.html'&&location.pathname!=='/privacy.html'&&location.pathname!=='/account.html')location.href='/legal.html'});
return {get legal(){return {...legal}},get user(){return user},get forks(){return new Map(forks)},get forkSync(){return {...forkSync}},get forkError(){return forkError},get syncing(){return syncing},syncForks,get enabled(){return enabled},get googleEnabled(){return googleEnabled},get ready(){return ready},get likedRepos(){return new Map(likedRepos)},get liked(){return new Set(liked)},get guestCount(){return guest.size},has:id=>[...liked].some(saved=>saved.toLowerCase()===id.toLowerCase()),busy:id=>[...pending].some(saved=>saved.toLowerCase()===id.toLowerCase()),toggle,refresh,signout,importGuest,request,friendlyError,statusMessage,track};
})();
